{"description":"Inspect OpenThoughts GitHub repo for deepseek tokens terminology","cmd":"python << 'EOF'
import urllib.request, json
# Look at the OpenThoughts repo tree / search for token counting code
urls = [
    "https://api.github.com/repos/open-thoughts/open-thoughts/git/trees/main?recursive=1",
]
try:
    with urllib.request.urlopen(urls[0], timeout=60) as r:
        data = json.load(r)
    for item in data.get("tree", []):
        p = item["path"]
        if any(k in p.lower() for k in ["token", "count", "metadata", "dataset", "process"]):
            print(item["path"])
except Exception as e:
    print("err", e)
EOF","yield_time_ms":60000}

