base = "https://raw.githubusercontent.com/open-thoughts/open-thoughts/main/open_thoughts/"
for f in ["analyze/analyze_length.py", "science/camel.py", "science/science.py", "reason.py"]:
    print("="*80)
    print("FILE:", f)
    try:
        with urllib.request.urlopen(base+f, timeout=60) as r:
